begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into fontex_beta.invitations(email) values ('recovery-admin@example.invalid'),('recovery-other@example.invalid');
insert into auth.users(id,email,email_confirmed_at) values
('fc010000-0000-4000-8000-000000000001','recovery-admin@example.invalid',now()),
('fc010000-0000-4000-8000-000000000002','recovery-other@example.invalid',now());
insert into fontex_ai.admins(user_id) values('fc010000-0000-4000-8000-000000000001');
select set_config('test.canvas.source','{"id":"recovery-scene","format":"primitive-scene","schemaVersion":2,"title":"Recovery","level":"secundaria","updatedAt":"2026-11-15T00:00:00Z","variables":[],"primitives":[],"conversation":[]}',true);
select set_config('test.canvas.reply','{"message":"Visible result","actions":[{"kind":"upsert_variable","variable":{"name":"b","value":2,"min":0,"max":10,"step":1,"unit":""}}]}',true);
select extensions.ok(not has_table_privilege('authenticated','fontex_ai.canvas_builds','select'),'clients cannot read raw private receipts');
select extensions.ok(not has_function_privilege('authenticated','public.complete_canvas_build(uuid,jsonb)','execute'),'clients cannot forge completion or charge settlement');
set local role service_role;
select extensions.is((public.begin_canvas_build('fc010000-0000-4000-8000-000000000001','fc010001-0000-4000-8000-000000000001',current_setting('test.canvas.source')::jsonb,'Build')->>'balance')::int,4,'receipt and credit reservation begin atomically');
select extensions.is(public.begin_canvas_build('fc010000-0000-4000-8000-000000000001','fc010001-0000-4000-8000-000000000001',current_setting('test.canvas.source')::jsonb,'Build')->>'reason','duplicate_request','retry cannot reserve or call provider again');
select extensions.throws_ok($$select public.begin_canvas_build('fc010000-0000-4000-8000-000000000002','fc010001-0000-4000-8000-000000000001',current_setting('test.canvas.source')::jsonb,'Build')$$,'22023',null,'request identity cannot be claimed by another user');
select extensions.is(public.complete_canvas_build('fc010001-0000-4000-8000-000000000001',current_setting('test.canvas.reply')::jsonb)->>'status','succeeded','valid proposal is stored with its charge');
select extensions.is((public.complete_canvas_build('fc010001-0000-4000-8000-000000000001',current_setting('test.canvas.reply')::jsonb)->>'balance')::int,4,'completion retry never charges again');
select extensions.throws_ok($$select public.complete_canvas_build('fc010001-0000-4000-8000-000000000001',jsonb_set(current_setting('test.canvas.reply')::jsonb,'{message}','"Different"'))$$,'22023',null,'a completed proposal cannot be replaced');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"fc010000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select extensions.is(public.get_canvas_build('fc010001-0000-4000-8000-000000000001'),null::jsonb,'another participant cannot recover a proposal');
select extensions.is(public.list_canvas_builds('recovery-scene'),'[]'::jsonb,'another participant cannot list receipt identities');
select public.ack_canvas_build('fc010001-0000-4000-8000-000000000001');
select set_config('request.jwt.claims','{"sub":"fc010000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select extensions.is(public.get_canvas_build('fc010001-0000-4000-8000-000000000001')->>'state','ready','owner recovers after a lost connection');
select extensions.is(public.get_canvas_build('fc010001-0000-4000-8000-000000000001')->'reply',current_setting('test.canvas.reply')::jsonb,'recovery delivers the exact saved proposal');
select extensions.is(public.get_canvas_build('fc010001-0000-4000-8000-000000000001')->'applied_at','null'::jsonb,'other participant cannot acknowledge the owner proposal');
select extensions.is(jsonb_array_length(public.list_canvas_builds('recovery-scene')),1,'owner can discover a result without a saved request ID');
select public.ack_canvas_build('fc010001-0000-4000-8000-000000000001');
select extensions.ok(public.get_canvas_build('fc010001-0000-4000-8000-000000000001')->>'applied_at' is not null,'application can be acknowledged separately from payment');
select extensions.throws_ok($$select public.admin_beta_overview()$$,'42501','admin_mfa_required','admin password alone cannot read participants');
select extensions.throws_ok($$select public.admin_grant_ai_credits('fc010000-0000-4000-8000-000000000001',1,'test',gen_random_uuid())$$,'42501','admin_mfa_required','admin password alone cannot grant credits');
select extensions.throws_ok($$select public.admin_canvas_diagnostics()$$,'42501','admin_mfa_required','diagnostics also requires a verified second factor');
select set_config('request.jwt.claims','{"sub":"fc010000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select extensions.lives_ok($$select public.admin_beta_overview()$$,'aal2 administrator can read the administrative panel');
select extensions.is((public.admin_canvas_diagnostics()->>'completed')::int,1,'diagnostics tracks completed requests');
select extensions.ok(not(public.admin_canvas_diagnostics() ? 'source_scene') and not(public.admin_canvas_diagnostics() ? 'question'),'diagnostics excludes lesson content and questions');
reset role;
-- Restore a receipt snapshot without changing Auth or user documents.
create temp table recovery_backup as select to_jsonb(b) as snapshot from fontex_ai.canvas_builds b where user_id='fc010000-0000-4000-8000-000000000001';
delete from fontex_ai.canvas_builds where user_id='fc010000-0000-4000-8000-000000000001';
insert into fontex_ai.canvas_builds select (jsonb_populate_record(null::fontex_ai.canvas_builds,snapshot)).* from recovery_backup;
select extensions.is((select to_jsonb(b) from fontex_ai.canvas_builds b where id='fc010001-0000-4000-8000-000000000001'),(select snapshot from recovery_backup),'receipt backup restores source, result and timestamps exactly');
update fontex_beta.members set active=false where user_id='fc010000-0000-4000-8000-000000000001';
set local role authenticated;
select extensions.throws_ok($$select public.get_canvas_build('fc010001-0000-4000-8000-000000000001')$$,'42501','beta_invitation_required','revocation immediately blocks receipt access with the existing JWT');
reset role;
update fontex_beta.members set active=true where user_id='fc010000-0000-4000-8000-000000000001';
set local role service_role;
select public.begin_canvas_build('fc010000-0000-4000-8000-000000000001','fc010001-0000-4000-8000-000000000002',current_setting('test.canvas.source')::jsonb,'Fail');
select public.finish_ai_generation('fc010001-0000-4000-8000-000000000002',false);
reset role;
set local role authenticated;
select extensions.is(public.get_canvas_build('fc010001-0000-4000-8000-000000000002')->>'state','refunded','failed request is visible as refunded');
select extensions.is((public.get_ai_credit_status()->>'balance')::int,4,'failed receipt restores exactly its reserved credit');
reset role;
update fontex_ai.canvas_builds set created_at=now()-interval '8 days' where id='fc010001-0000-4000-8000-000000000001';
set local role authenticated;
select extensions.is(public.get_canvas_build('fc010001-0000-4000-8000-000000000001'),null::jsonb,'expired recovery content is no longer exposed');
select extensions.finish();
rollback;
